16		_ "modernc.org/sqlite"
17	)
18	
19	// The search store is the committed-tree search snapshot persisted as sqlite
20	// instead of one gzipped JSON document. The JSON form must be decoded in full,
21	// single-threaded, before the first query can run — measured at 3.1s of an 8s
22	// warm query on a 52k-symbol repository. The store keeps every record as a
23	// typed row (id, name, path and relation endpoints are real indexed columns)
24	// plus the record's canonical JSON, so a full load decodes rows in parallel
25	// and later consumers can read subsets by index without materializing the
26	// whole snapshot at all.
27	//
28	// Fidelity contract: loading a store must reproduce the cachedSearchSnapshot
29	// that built it exactly (TestSearchStoreRoundTripsSnapshot pins DeepEqual),
30	// so the store can substitute for the JSON entry with zero behavior change.
31	//
32	// searchStoreVersion follows the same rules as the other cache versions: bump
33	// it whenever the stored shape or the producer's rules change. The store is a
34	// derived sibling of the search snapshot entry and shares its key.
35	const searchStoreVersion = "search-store-sqlite-v1"
36	
37	// searchStoreEnabled gates the READ path while the store rolls out: the
38	// artifact is always written beside the JSON entry, but it is only served when
39	// the operator opts in, so a rollout problem degrades to the measured JSON
40	// path rather than to a broken query.
41	func searchStoreEnabled(lookupEnv func(string) (string, bool)) bool {
42		if lookupEnv == nil {
43			lookupEnv = os.LookupEnv
44		}
45		value, ok := lookupEnv("ENTIRE_GRAPH_SEARCH_STORE")
46		if !ok {
47			return false
48		}
49		switch strings.TrimSpace(strings.ToLower(value)) {
50		case "", "0", "false", "off", "no":
51			return false
52		}
53		return true
54	}
55	
56	const searchStoreSchema = `
57	CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) WITHOUT ROWID;
58	CREATE TABLE files (
59		path TEXT PRIMARY KEY,
60		lines INTEGER NOT NULL,
61		record TEXT NOT NULL
62	);
63	CREATE TABLE externals (id TEXT PRIMARY KEY, record TEXT NOT NULL);
64	CREATE TABLE symbols (
65		id TEXT PRIMARY KEY,
66		name TEXT NOT NULL,
67		qualified_name TEXT NOT NULL,
68		file_path TEXT NOT NULL,
69		kind TEXT NOT NULL,
70		local INTEGER NOT NULL,
71		bodyless INTEGER NOT NULL,
72		name_line INTEGER NOT NULL,
73		byte_start INTEGER,
74		byte_end INTEGER,
75		param_names TEXT,
76		param_names_known INTEGER NOT NULL,
77		sig_param_types TEXT,
78		sig_return_types TEXT,
79		has_signature_types INTEGER NOT NULL,
80		record TEXT NOT NULL
81	);
82	CREATE INDEX symbols_name ON symbols(name);
83	CREATE INDEX symbols_qualified_name ON symbols(qualified_name);
84	CREATE INDEX symbols_file_path ON symbols(file_path);
85	CREATE TABLE relations (
86		from_id TEXT NOT NULL,
87		to_id TEXT NOT NULL,
88		type TEXT NOT NULL,
89		record TEXT NOT NULL
90	);
91	CREATE INDEX relations_from ON relations(from_id);
92	CREATE INDEX relations_to ON relations(to_id);
93	CREATE INDEX relations_type ON relations(type);
94	CREATE TABLE unmerged_data_flow_edges (from_id TEXT NOT NULL, to_id TEXT NOT NULL);
95	`
96	
97	// searchStoreMeta holds the envelope fields that are not record streams. The
98	// header and the envelope scalars travel as JSON under single meta keys; they
99	// are tiny and never read selectively.
100	type searchStoreMeta struct {
101		CacheVersion    string  `json:"cache_version"`
102		ProviderVersion string  `json:"provider_version"`
103		Commit          string  `json:"commit"`
104		Tree            string  `json:"tree"`
105		Profile         Profile `json:"profile"`
106		MaxParseBytes   int     `json:"max_parse_bytes"`
107		Worktree        bool    `json:"worktree,omitempty"`
108		DerivedFrom     string  `json:"derived_from,omitempty"`
109		RepoScope       string  `json:"repo_scope,omitempty"`
110	}
111	
112	// buildSearchStore writes cache as a sqlite store at path, which must not
113	// exist (an empty file is fine — sqlite adopts it). entryDigest is the digest
114	// of the gz JSON entry this store mirrors; readers compare it against the
115	// entry on disk, so a sidecar that survived a later entry rewrite reads as
116	// absent rather than serving a stale snapshot. The build runs with journaling
117	// off: the file is a temporary the caller renames into place on success and
118	// removes on failure, so a crashed build can never be read as an entry.
119	func buildSearchStore(ctx context.Context, path, entryDigest string, cache *cachedSearchSnapshot) error {
120		db, err := sql.Open("sqlite", "file:"+sqliteURLPath(path)+"?_pragma=journal_mode(OFF)&_pragma=synchronous(OFF)")
121		if err != nil {
122			return err
123		}
124		defer db.Close()
125		if _, err := db.ExecContext(ctx, searchStoreSchema); err != nil {
126			return err
127		}
128		tx, err := db.BeginTx(ctx, nil)
129		if err != nil {
130			return err
131		}
132		committed := false
133		defer func() {
134			if !committed {
135				_ = tx.Rollback()
136			}
137		}()
138	
139		putMeta, err := tx.PrepareContext(ctx, `INSERT INTO meta(key, value) VALUES (?, ?)`)
140		if err != nil {
141			return err
142		}
143		defer putMeta.Close()
144		meta := searchStoreMeta{
145			CacheVersion:    cache.CacheVersion,
146			ProviderVersion: cache.ProviderVersion,
147			Commit:          cache.Commit,
148			Tree:            cache.Tree,
149			Profile:         cache.Profile,
150			MaxParseBytes:   cache.MaxParseBytes,
151			Worktree:        cache.Worktree,
152			DerivedFrom:     cache.DerivedFrom,
153			RepoScope:       cache.RepoScope,
154		}
155		for key, value := range map[string]any{
156			"store_version": searchStoreVersion,
157			"entry_digest":  entryDigest,
158			"envelope":      meta,
159			"header":        cache.Snapshot.Header,
160		} {
161			encoded, err := json.Marshal(value)
162			if err != nil {
163				return err
164			}
165			if _, err := putMeta.ExecContext(ctx, key, string(encoded)); err != nil {
166				return err
167			}
168		}
169	
170		putFile, err := tx.PrepareContext(ctx, `INSERT INTO files(path, lines, record) VALUES (?, ?, ?)`)
171		if err != nil {
172			return err
173		}
174		defer putFile.Close()
175		for index := range cache.Snapshot.Files {
176			file := &cache.Snapshot.Files[index]
177			record, err := json.Marshal(file)
178			if err != nil {
179				return err
180			}
181			// FileLines is keyed by the file record's ID, not its path, and only
182			// holds nonzero counts (see newCachedSearchSnapshot); the column
183			// mirrors that so restoreCachedSearchInternals reproduces records
184			// exactly.
185			if _, err := putFile.ExecContext(ctx, file.Path, cache.FileLines[file.ID], string(record)); err != nil {
186				return err
187			}
188		}
189	
190		putExternal, err := tx.PrepareContext(ctx, `INSERT INTO externals(id, record) VALUES (?, ?)`)
191		if err != nil {
192			return err
193		}
194		defer putExternal.Close()
195		for index := range cache.Snapshot.Externals {
196			external := &cache.Snapshot.Externals[index]
197			record, err := json.Marshal(external)
198			if err != nil {
199				return err
200			}
201			if _, err := putExternal.ExecContext(ctx, external.ID, string(record)); err != nil {
202				return err
203			}
204		}
205	
206		local := make(map[string]bool, len(cache.LocalSymbolIDs))
207		for _, id := range cache.LocalSymbolIDs {
208			local[id] = true
209		}
210		bodyless := make(map[string]bool, len(cache.BodylessSymbolIDs))
211		for _, id := range cache.BodylessSymbolIDs {
212			bodyless[id] = true
213		}
214		paramKnown := make(map[string]bool, len(cache.SymbolParameterNamesKnownIDs))
215		for _, id := range cache.SymbolParameterNamesKnownIDs {
216			paramKnown[id] = true
217		}
218		putSymbol, err := tx.PrepareContext(ctx, `INSERT INTO symbols(
219			id, name, qualified_name, file_path, kind, local, bodyless, name_line,
220			byte_start, byte_end, param_names, param_names_known,
221			sig_param_types, sig_return_types, has_signature_types, record
222		) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
223		if err != nil {
224			return err
225		}
226		defer putSymbol.Close()
227		for index := range cache.Snapshot.Symbols {
228			symbol := &cache.Snapshot.Symbols[index]
229			record, err := json.Marshal(symbol)
230			if err != nil {
231				return err
232			}
233			var byteStart, byteEnd any
234			if byteRange, ok := cache.SymbolByteRanges[symbol.ID]; ok {
235				byteStart, byteEnd = byteRange.Start, byteRange.End
236			}
237			var paramNames any
238			if names, ok := cache.SymbolParameterNames[symbol.ID]; ok {
239				encoded, err := json.Marshal(names)
240				if err != nil {
241					return err
242				}
243				paramNames = string(encoded)
244			}
245			var sigParams, sigReturns any
246			hasSignatureTypes := false
247			if types, ok := cache.SymbolSignatureTypes[symbol.ID]; ok {
248				sigParams, sigReturns = types.Params, types.Returns
249				hasSignatureTypes = true
250			}
251			if _, err := putSymbol.ExecContext(ctx,
252				symbol.ID, symbol.Name, symbol.QualifiedName, symbol.FilePath, symbol.Kind,
253				boolToInt(local[symbol.ID]), boolToInt(bodyless[symbol.ID]), cache.SymbolNameLines[symbol.ID],
254				byteStart, byteEnd, paramNames, boolToInt(paramKnown[symbol.ID]),
255				sigParams, sigReturns, boolToInt(hasSignatureTypes), string(record),
256			); err != nil {
257				return err
258			}
259		}
260	
261		putRelation, err := tx.PrepareContext(ctx, `INSERT INTO relations(from_id, to_id, type, record) VALUES (?, ?, ?, ?)`)
262		if err != nil {
263			return err
264		}
265		defer putRelation.Close()
266		for index := range cache.Snapshot.Relations {
267			relation := &cache.Snapshot.Relations[index]
268			record, err := json.Marshal(relation)
269			if err != nil {
270				return err
271			}
272			if _, err := putRelation.ExecContext(ctx, relation.FromID, relation.ToID, relation.Type, string(record)); err != nil {
273				return err
274			}
275		}
276	
277		putUnmerged, err := tx.PrepareContext(ctx, `INSERT INTO unmerged_data_flow_edges(from_id, to_id) VALUES (?, ?)`)
278		if err != nil {
279			return err
280		}
281		defer putUnmerged.Close()
282		for key := range cache.Snapshot.unmergedDataFlowEdges {
283			fromID, toID, _ := strings.Cut(key, "\x00")
284			if _, err := putUnmerged.ExecContext(ctx, fromID, toID); err != nil {
285				return err
286			}
287		}
288	
289		if err := tx.Commit(); err != nil {
290			return err
291		}
292		committed = true
293		return nil
294	}
295	
296	func boolToInt(value bool) int {
297		if value {
298			return 1
299		}
300		return 0
301	}
302	
303	// sqliteURLPath encodes a filesystem path for a file: DSN. Query separators in
304	// a legitimate path would otherwise be parsed as DSN parameters.
305	func sqliteURLPath(path string) string {
306		return (&url.URL{Path: filepath.ToSlash(path)}).EscapedPath()
307	}
308	
309	// loadSearchStore reads a store written by buildSearchStore back into the
310	// cachedSearchSnapshot it was built from. wantEntryDigest, when non-empty,
311	// must match the digest the store was built against. Row JSON decodes on all
312	// cores: the monolithic JSON entry this replaces decodes single-threaded by
313	// nature, and the parallel row decode is where the load-time win comes from
314	// until consumers stop materializing the whole snapshot.
315	func loadSearchStore(ctx context.Context, path, wantEntryDigest string) (cachedSearchSnapshot, error) {
316		db, err := sql.Open("sqlite", "file:"+sqliteURLPath(path)+"?immutable=1&mode=ro")
317		if err != nil {
318			return cachedSearchSnapshot{}, err
319		}
320		defer db.Close()
321	
322		var cache cachedSearchSnapshot
323		var storeVersion string
324		if err := readSearchStoreMetaKey(ctx, db, "store_version", &storeVersion); err != nil {
325			return cachedSearchSnapshot{}, err
326		}
327		if storeVersion != searchStoreVersion {
328			return cachedSearchSnapshot{}, fmt.Errorf("search store version %q, want %q", storeVersion, searchStoreVersion)
329		}
330		if wantEntryDigest != "" {
331			var entryDigest string
332			if err := readSearchStoreMetaKey(ctx, db, "entry_digest", &entryDigest); err != nil {
333				return cachedSearchSnapshot{}, err
334			}
335			if entryDigest != wantEntryDigest {
336				return cachedSearchSnapshot{}, errors.New("search store does not match the current snapshot entry")
337			}
338		}
339		var meta searchStoreMeta
340		if err := readSearchStoreMetaKey(ctx, db, "envelope", &meta); err != nil {
341			return cachedSearchSnapshot{}, err
342		}
343		cache.CacheVersion = meta.CacheVersion
344		cache.ProviderVersion = meta.ProviderVersion
345		cache.Commit = meta.Commit
346		cache.Tree = meta.Tree
347		cache.Profile = meta.Profile
348		cache.MaxParseBytes = meta.MaxParseBytes
349		cache.Worktree = meta.Worktree
350		cache.DerivedFrom = meta.DerivedFrom
351		cache.RepoScope = meta.RepoScope
352		if err := readSearchStoreMetaKey(ctx, db, "header", &cache.Snapshot.Header); err != nil {
353			return cachedSearchSnapshot{}, err
354		}
355	
356		if err := scanSearchStoreRows(ctx, db, `SELECT lines, record FROM files ORDER BY rowid`, func(scan rowScanner) error {
357			var record string
358			var lines int
359			if err := scan(&lines, &record); err != nil {
360				return err
361			}
362			var file FileRecord
363			if err := json.Unmarshal([]byte(record), &file); err != nil {
364				return err
365			}
366			cache.Snapshot.Files = append(cache.Snapshot.Files, file)
367			if lines != 0 {
368				if cache.FileLines == nil {
369					cache.FileLines = make(map[string]int)
370				}
371				cache.FileLines[file.ID] = lines
372			}
373			return nil
374		}); err != nil {
375			return cachedSearchSnapshot{}, err
376		}
377	
378		if err := scanSearchStoreRows(ctx, db, `SELECT record FROM externals ORDER BY rowid`, func(scan rowScanner) error {
379			var record string
380			if err := scan(&record); err != nil {
381				return err
382			}
383			var external ExternalRecord
384			if err := json.Unmarshal([]byte(record), &external); err != nil {
385				return err
386			}
387			cache.Snapshot.Externals = append(cache.Snapshot.Externals, external)
388			return nil
389		}); err != nil {
390			return cachedSearchSnapshot{}, err
391		}
392	
393		type symbolRow struct {
394			record            string
395			local, bodyless   bool
396			nameLine          int
397			byteStart         sql.NullInt64
398			byteEnd           sql.NullInt64
399			paramNames        sql.NullString
400			paramKnown        bool
401			sigParams         sql.NullString
402			sigReturns        sql.NullString
403			hasSignatureTypes bool
404		}
405		var symbolRows []symbolRow
406		if err := scanSearchStoreRows(ctx, db, `SELECT record, local, bodyless, name_line, byte_start, byte_end,
407			param_names, param_names_known, sig_param_types, sig_return_types, has_signature_types
408			FROM symbols ORDER BY rowid`, func(scan rowScanner) error {
409			var row symbolRow
410			if err := scan(&row.record, &row.local, &row.bodyless, &row.nameLine, &row.byteStart, &row.byteEnd,
411				&row.paramNames, &row.paramKnown, &row.sigParams, &row.sigReturns, &row.hasSignatureTypes); err != nil {
412				return err
413			}
414			symbolRows = append(symbolRows, row)
415			return nil
416		}); err != nil {
417			return cachedSearchSnapshot{}, err
418		}
419		cache.Snapshot.Symbols = make([]SymbolRecord, len(symbolRows))
420		cache.SymbolByteRanges = map[string]cachedSymbolByteRange{}
421		cache.SymbolNameLines = map[string]int{}
422		cache.SymbolParameterNames = map[string][]string{}
423		cache.SymbolSignatureTypes = map[string]cachedSignatureTypes{}
424		if err := decodeSearchStoreParallel(len(symbolRows), func(index int) error {
425			return json.Unmarshal([]byte(symbolRows[index].record), &cache.Snapshot.Symbols[index])
426		}); err != nil {
427			return cachedSearchSnapshot{}, err
428		}
429		for index := range symbolRows {
430			row := &symbolRows[index]
431			id := cache.Snapshot.Symbols[index].ID
432			if row.local {
433				cache.LocalSymbolIDs = append(cache.LocalSymbolIDs, id)
434			}
435			if row.bodyless {
436				cache.BodylessSymbolIDs = append(cache.BodylessSymbolIDs, id)
437			}
438			if row.nameLine != 0 {
439				cache.SymbolNameLines[id] = row.nameLine
440			}
441			if row.byteStart.Valid && row.byteEnd.Valid {
442				cache.SymbolByteRanges[id] = cachedSymbolByteRange{Start: int(row.byteStart.Int64), End: int(row.byteEnd.Int64)}
443			}
444			if row.paramNames.Valid {
445				var names []string
446				if err := json.Unmarshal([]byte(row.paramNames.String), &names); err != nil {
447					return cachedSearchSnapshot{}, err
448				}
449				cache.SymbolParameterNames[id] = names
450			}
451			if row.paramKnown {
452				cache.SymbolParameterNamesKnownIDs = append(cache.SymbolParameterNamesKnownIDs, id)
453			}
454			if row.hasSignatureTypes {
455				cache.SymbolSignatureTypes[id] = cachedSignatureTypes{
456					Params:  row.sigParams.String,
457					Returns: row.sigReturns.String,
458				}
459			}
460		}
461	
462		var relationRows []string
463		if err := scanSearchStoreRows(ctx, db, `SELECT record FROM relations ORDER BY rowid`, func(scan rowScanner) error {
464			var record string
465			if err := scan(&record); err != nil {
466				return err
467			}
468			relationRows = append(relationRows, record)
469			return nil
470		}); err != nil {
471			return cachedSearchSnapshot{}, err
472		}
473		cache.Snapshot.Relations = make([]RelationRecord, len(relationRows))
474		if err := decodeSearchStoreParallel(len(relationRows), func(index int) error {
475			return json.Unmarshal([]byte(relationRows[index]), &cache.Snapshot.Relations[index])
476		}); err != nil {
477			return cachedSearchSnapshot{}, err
478		}
479	
480		if err := scanSearchStoreRows(ctx, db, `SELECT from_id, to_id FROM unmerged_data_flow_edges ORDER BY rowid`, func(scan rowScanner) error {
481			var fromID, toID string
482			if err := scan(&fromID, &toID); err != nil {
483				return err
484			}
485			cache.UnmergedDataFlowEdges = append(cache.UnmergedDataFlowEdges, [2]string{fromID, toID})
486			return nil
487		}); err != nil {
488			return cachedSearchSnapshot{}, err
489		}
490	
491		restoreCachedSearchInternals(&cache)
492		return cache, nil
493	}
494	
495	func readSearchStoreMetaKey(ctx context.Context, db *sql.DB, key string, value any) error {
496		var encoded string
497		if err := db.QueryRowContext(ctx, `SELECT value FROM meta WHERE key = ?`, key).Scan(&encoded); err != nil {
498			if errors.Is(err, sql.ErrNoRows) {
499				return fmt.Errorf("search store is missing meta key %q", key)
500			}
501			return err
502		}
503		return json.Unmarshal([]byte(encoded), value)
504	}
505	
506	type rowScanner func(dest ...any) error
507	
508	func scanSearchStoreRows(ctx context.Context, db *sql.DB, query string, each func(rowScanner) error) error {
509		rows, err := db.QueryContext(ctx, query)
510		if err != nil {
511			return err
512		}
513		defer rows.Close()
514		for rows.Next() {
515			if err := each(rows.Scan); err != nil {
516				return err
517			}
518		}
519		return rows.Err()
520	}
521	
522	// decodeSearchStoreParallel runs decode(i) for every index on all cores. The
523	// per-row JSON decode dominates a full load, and rows are independent.
524	func decodeSearchStoreParallel(count int, decode func(int) error) error {
525		if count == 0 {
526			return nil
527		}
528		workers := min(count, runtime.GOMAXPROCS(0))
529		var group sync.WaitGroup
530		errs := make([]error, workers)
531		chunk := (count + workers - 1) / workers
532		for worker := range workers {
533			start := worker * chunk
534			end := min(start+chunk, count)
535			if start >= end {
536				break
537			}
538			group.Go(func() {
539				for index := start; index < end; index++ {
540					if err := decode(index); err != nil {
541						errs[worker] = fmt.Errorf("search store row %d: %w", index, err)
542						return
543					}
544				}
545			})
546		}
547		group.Wait()
548		return errors.Join(errs...)
549	}
550	
551	// searchStorePathForEntry names the store artifact beside a search snapshot
552	// cache entry: the entry's path with the .sqlite suffix replacing .json.gz.
553	func searchStorePathForEntry(entry cacheEntry) string {
554		relative := strings.TrimSuffix(entry.relative, ".json.gz") + ".sqlite"
555		return filepath.Join(entry.root, relative)
556	}
557	
558	// writeSearchStoreSidecar builds the sqlite sidecar for an entry that was just
559	// written with entryDigest. It goes through the same confined directory walk
560	// every cache write uses, builds into a temporary, and renames into place. On
561	// ANY failure it removes both the temporary and any previous sidecar: the
562	// invariant readers rely on is that a sidecar present on disk was written by
563	// the same call that wrote the current entry (the digest check backstops the
564	// crash window between the two renames).
565	func writeSearchStoreSidecar(ctx context.Context, entry cacheEntry, entryDigest string, cache *cachedSearchSnapshot) error {
566		if err := os.MkdirAll(entry.root, 0o700); err != nil {
567			return err
568		}
569		root, err := os.OpenRoot(entry.root)
570		if err != nil {
571			return err
572		}
573		defer root.Close()
574		directory, err := openCacheDirectory(root, filepath.Dir(entry.relative))
575		if err != nil {
